mkdir -p app/scraper tests/fixtures && cat > /tmp/devalue_proto.py <<'PYEOF'
import json, re, sys

HOLE, UNDEFINED, NAN, POS_INF, NEG_INF, NEG_ZERO = -1, -2, -3, -4, -5, -6

def parse(flat):
    if isinstance(flat, (int, float)) or flat is None:
        return None
    hydrated = {}
    def hydrate(index, stack=()):
        if index == UNDEFINED: return None
        if index == NAN: return float('nan')
        if index == POS_INF: return float('inf')
        if index == NEG_INF: return float('-inf')
        if index == NEG_ZERO: return -0.0
        if index in hydrated: return hydrated[index]
        value = flat[index]
        if not isinstance(value, (list, dict)):
            hydrated[index] = value
            return value
        if isinstance(value, list):
            if value and isinstance(value[0], str):
                t = value[0]
                if t == 'Date':
                    out = value[1]; hydrated[index]=out; return out
                if t == 'Set':
                    out = []; hydrated[index]=out
                    out.extend(hydrate(i) for i in value[1:]); return out
                if t == 'Map':
                    out = {}; hydrated[index]=out
                    for i in range(1, len(value), 2):
                        out[str(hydrate(value[i]))] = hydrate(value[i+1])
                    return out
                if t in ('BigInt','RegExp','URL'):
                    out = value[1]; hydrated[index]=out; return out
                if t == 'Object':
                    out = value[1]; hydrated[index]=out; return out
                if t == 'null':
                    out = {}; hydrated[index]=out
                    for i in range(1, len(value), 2):
                        out[flat[value[i]]] = hydrate(value[i+1])
                    return out
                # nuxt reviver: ["Ref", idx] etc
                if len(value) == 2 and isinstance(value[1], int):
                    out = hydrate(value[1]); hydrated[index] = out; return out
            out = []; hydrated[index] = out
            out.extend(hydrate(i) for i in value)
            return out
        out = {}; hydrated[index] = out
        for k, v in value.items():
            out[k] = hydrate(v)
        return out
    return hydrate(0)

h = open(sys.argv[1], encoding='utf-8').read()
m = re.search(r'<script[^>]*id="__NUXT_DATA__"[^>]*>(.*?)</script>', h, re.S)
flat = json.loads(m.group(1))
print('flat len', len(flat))
data = parse(flat)
json.dump(data, open(sys.argv[2],'w'), indent=1, ensure_ascii=False, default=str)
print('written')
PYEOF
.venv/bin/python /tmp/devalue_proto.py /tmp/mc_game_card.html /tmp/card.json && ls -la /tmp/card.json

