# Install: copy to /etc/systemd/system/, then
#   sudo systemctl daemon-reload && sudo systemctl enable --now metacritic-ai-watch
[Unit]
Description=Metacritic AI Watch — hourly game crawler and web catalogue
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=ubuntu
Group=ubuntu
WorkingDirectory=/srv/skytec/metacritic-ai-watch
EnvironmentFile=/srv/skytec/metacritic-ai-watch/.env
ExecStart=/srv/skytec/metacritic-ai-watch/.venv/bin/uvicorn app.main:app --host 127.0.0.1 --port 8010
Restart=always
RestartSec=5
# The scheduler owns its own timing; give a crawl in flight a moment to finish.
TimeoutStopSec=30
KillSignal=SIGINT

MemoryMax=1G
# Whisper needs far more than this. Raise it if YOUTUBE_WHISPER_ENABLED=1.

NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=full
ProtectHome=read-only
ReadWritePaths=/srv/skytec/metacritic-ai-watch/data

StandardOutput=journal
StandardError=journal
SyslogIdentifier=metacritic-ai-watch

[Install]
WantedBy=multi-user.target
EOF
cat > deploy/nginx.conf <<'EOF'
# Replace ${DOMAIN} with the real host name, then:
#   sudo cp deploy/nginx.conf /etc/nginx/sites-available/metacritic-ai-watch
#   sudo ln -s /etc/nginx/sites-available/metacritic-ai-watch /etc/nginx/sites-enabled/
#   sudo nginx -t && sudo systemctl reload nginx
#   sudo certbot --nginx -d ${DOMAIN}     # adds the TLS block below

server {
    listen 80;
    listen [::]:80;
    server_name ${DOMAIN};

    # certbot rewrites this to a 301 once the certificate exists.
    location / {
        proxy_pass http://127.0.0.1:8010;
        proxy_http_version 1.1;
        proxy_set_header Host              $host;
        proxy_set_header X-Real-IP         $remote_addr;
        proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_read_timeout 60s;
    }

    # Server-sent events: nothing may sit in a buffer, and the connection lives
    # longer than a normal request (the app closes it itself after 5 minutes).
    location = /monitor/stream {
        proxy_pass http://127.0.0.1:8010;
        proxy_http_version 1.1;
        proxy_set_header Host              $host;
        proxy_set_header X-Real-IP         $remote_addr;
        proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Connection        "";

        proxy_buffering off;
        proxy_cache off;
        gzip off;
        chunked_transfer_encoding on;
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
    }

    # Covers and the stylesheet are immutable enough to cache at the edge.
    location ~ ^/(static|covers)/ {
        proxy_pass http://127.0.0.1:8010;
        proxy_set_header Host $host;
        expires 1d;
        add_header Cache-Control "public";
    }

    client_max_body_size 1m;
    access_log /var/log/nginx/metacritic-ai-watch.access.log;
    error_log  /var/log/nginx/metacritic-ai-watch.error.log;
}
EOF
